mapper.update:
UPDATE EXTRACT_ELEC_DOC
SET SUMMARY = #{summary},
    SUMMARY_FLAG = #{flag},
    LLM_SUMMARY_STATUS = 'PASS',
    LLM_SUMMARY_ERR_MSG = NULL,
    SUMMARY_TIME = NOW(3),
    UPDATE_DATE = NOW()
WHERE FILE_NAME = #{target.fileName}
  AND RC_RFILE_NO = #{target.rcRfileNo}
  AND RC_RITEM_NO = #{target.rcRitemNo}
  AND ZIP_SEQ = #{target.zipSeq}

UPDATE EXTRACT_ELEC_DOC
SET SUMMARY_FLAG = 'N',
    LLM_SUMMARY_STATUS = 'FAIL',
    LLM_SUMMARY_ERR_MSG = #{errorMessage},
    SUMMARY_TIME = NOW(3),
    UPDATE_DATE = NOW()
WHERE FILE_NAME = #{target.fileName}
  AND RC_RFILE_NO = #{target.rcRfileNo}
  AND RC_RITEM_NO = #{target.rcRitemNo}
  AND ZIP_SEQ = #{target.zipSeq}
